<?php
declare(strict_types=1);namespace App\Application\Payments;
use App\Application\{Audit\AuditWriter,Events\OutboxWriter};use App\Models\PaymentIntentRecord;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;
final class WebhookProcessingService{private const TRANSITIONS=['PENDING_CUSTOMER'=>['PROCESSING','SUCCEEDED','FAILED','EXPIRED'],'PROCESSING'=>['SUCCEEDED','FAILED','EXPIRED'],'SUCCEEDED'=>['REFUNDED','CHARGED_BACK'],'FAILED'=>[],'EXPIRED'=>[],'REFUNDED'=>[],'CHARGED_BACK'=>[]];public function __construct(private AuditWriter$audit,private OutboxWriter$outbox){}public function verify(string$p,string$body,int$timestamp,string$sig):void{$secret=(string)config("payments.providers.$p.webhook_secret");if($secret===''||$timestamp===0||abs(time()-$timestamp)>(int)config('payments.webhook_tolerance_seconds',300)||!hash_equals(hash_hmac('sha256',$timestamp.'.'.$body,$secret),$sig))throw ValidationException::withMessages(['signature'=>__('wave4.webhook_auth_failed')]);}public function process(string$p,string$event,array$payload,string$sig):void{DB::transaction(function()use($p,$event,$payload,$sig){$inserted=DB::table('webhook_inbox')->insertOrIgnore(['id'=>(string)Str::uuid(),'provider'=>$p,'external_event_id'=>$event,'signature_hash'=>hash('sha256',$sig),'payload'=>json_encode($payload),'received_at'=>now(),'status'=>'RECEIVED','processing_attempts'=>1]);if(!$inserted)return;$i=PaymentIntentRecord::where(['provider'=>$p,'provider_reference'=>$payload['payment_reference']])->lockForUpdate()->first();if(!$i)return$this->fail($p,$event,'UNKNOWN_PAYMENT');if($i->amount_minor!==(int)$payload['amount_minor']||$i->currency!==$payload['currency'])return$this->fail($p,$event,'AMOUNT_OR_CURRENCY_MISMATCH');$next=$payload['status'];if(!in_array($next,self::TRANSITIONS[$i->status]??[],true)&&$next!==$i->status)return$this->fail($p,$event,'INVALID_STATUS_TRANSITION');$previous=$i->status;$i->update(['status'=>$next,'provider_snapshot'=>$payload]);DB::table('payment_events')->insert(['id'=>(string)Str::uuid(),'payment_intent_id'=>$i->id,'type'=>'PROVIDER_STATUS','provider_event_id'=>$event,'previous_status'=>$previous,'new_status'=>$next,'amount_minor'=>$i->amount_minor,'currency'=>$i->currency,'provider_payload'=>json_encode($payload),'occurred_at'=>now()]);DB::table('webhook_inbox')->where(['provider'=>$p,'external_event_id'=>$event])->update(['status'=>'PROCESSED','processed_at'=>now()]);$this->audit->record('payment.webhook.processed','payment_intent',$i->id,['status'=>$next]);$this->outbox->record('payment.status.changed','payment_intent',$i->id,['payment_intent_id'=>$i->id,'previous'=>$previous,'status'=>$next]);});}private function fail(string$p,string$e,string$r):void{DB::table('webhook_inbox')->where(['provider'=>$p,'external_event_id'=>$e])->update(['status'=>'FAILED','failure_reason'=>$r]);}}
